947	fn create_worktree(repo_dir: &str, branch: &str) -> String {
948	    let repo_path = std::path::Path::new(repo_dir);
949	    let parent = match repo_path.parent() {
950	        Some(p) => p,
951	        None => return "Error: cannot determine repo parent directory".to_string(),
952	    };
953	    let repo_name = repo_path
954	        .file_name()
955	        .map(|s| s.to_string_lossy().to_string())
956	        .unwrap_or_else(|| "repo".to_string());
957	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
958	
959	    // Try -b (new branch) first; fall back to checking out an existing branch.
960	    let out = std::process::Command::new("git")
961	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
962	        .current_dir(repo_dir)
963	        .output();
964	
965	    match out {
966	        Err(e) => format!("Error: {e}"),
967	        Ok(o) if o.status.success() => {
968	            format!("Created worktree: {}", short_path_s(wt_path.to_str().unwrap_or("")))
969	        }
970	        Ok(o) => {
971	            let msg = String::from_utf8_lossy(&o.stderr);
972	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
973	            format!("Error: {first}")
974	        }
975	    }
976	}
