                let pad = w.saturating_sub(vis);
                write!(buf, "\x1b[{sel_bg}m{line_bg}{}\x1b[0m", " ".repeat(pad))?;
            } else {
                buf.extend_from_slice(line.as_bytes());
            }
        }
    }

