let mut segs = params.split(';').peekable();

while let Some(seg) = segs.next() {
    // Upgrade dim/faint foreground so it stays readable on the selection bg.
    if seg == t.text_dim || seg == t.text_faint {
        non_bg.push(t.sel_text_dim);
        found_dim = true;
        continue;
    }
    match seg {
        // Standard background colours 40-47 and bright 100-107
        "40"|"41"|"42"|"43"|"44"|"45"|"46"|"47"
        |"100"|"101"|"102"|"103"|"104"|"105"|"106"|"107" => {
            found_bg = true;
        }
        // 256-colour or true-colour background: 48;5;N or 48;2;R;G;B
        "48" => {
            found_bg = true;
            match segs.next().as_deref() {
                Some("5") => { segs.next(); }          // skip N
                Some("2") => { segs.next(); segs.next(); segs.next(); } // skip R;G;B
                _ => {}
            }
        }
        // \x1b[49m — reset background to default (termimad uses this, not \x1b[0m)
        "49" => { found_bg = true; }
        // Reset within a combined sequence — keep it
        "0" => non_bg.push("0"),
        other => non_bg.push(other),
    }
}

if !found_bg {
    // If a dim colour was substituted, emit the modified sequence without
    // reinserting a background (there was none to replace).
    if found_dim {
        return if non_bg.is_empty() {
            String::new()
        } else {
            format!("\x1b[{}m", non_bg.join(";"))
        };
    }
    return format!("\x1b[{params}m");
}

