// selection background rather than overriding it.
// Dim/faint foreground colors are upgraded via simple pre-substitution so
// they remain legible on the selection background.
fn with_bg(s: &str, bg: &str) -> String {
    let t = crate::theme::get();
    let dim_esc   = format!("\x1b[{}m", t.text_dim);
    let faint_esc = format!("\x1b[{}m", t.text_faint);
    let sel_dim   = format!("\x1b[{}m", t.sel_text_dim);
    let s_upd = s.replace(&dim_esc, &sel_dim).replace(&faint_esc, &sel_dim);
    let s = s_upd.as_str();

    let bg_seq  = format!("\x1b[{bg}m");
    let mut out = bg_seq.clone();
    let bytes   = s.as_bytes();
    let mut i   = 0;

    while i < bytes.len() {
        if bytes[i] == b'\x1b' && bytes.get(i + 1) == Some(&b'[') {
            // Parse CSI sequence: ESC [ <params> <cmd>
            let esc_start   = i;
            i += 2;
            let params_start = i;
            while i < bytes.len() && !bytes[i].is_ascii_alphabetic() { i += 1; }
            let cmd    = *bytes.get(i).unwrap_or(&b'm');
            let params = &s[params_start..i];
            i += 1;

            if cmd == b'm' {
                out.push_str(&rewrite_sgr(params, &bg_seq));
            } else {
                out.push_str(&s[esc_start..i]);
            }
        } else {
            let ch_len = s[i..].chars().next().map_or(1, |c| c.len_utf8());
            out.push_str(&s[i..i + ch_len]);
            i += ch_len;
        }
    }

    out
}

